changeSet.sql:
CREATE TABLE IF NOT EXISTS app.company ( delete_flag INTEGER DEFAULT 0, company_id BIGSERIAL NOT NULL, company_name VARCHAR(100) NOT NULL, company_address VARCHAR(255), company_email_id VARCHAR(50) NOT NULL, max_users INTEGER, created_by BIGINT, created_date_time TIMESTAMPTZ(6), updated_by BIGINT, updated_date_time TIMESTAMPTZ(6), CONSTRAINT company_pkey PRIMARY KEY (company_id), CONSTRAINT company_email_id_key UNIQUE (company_email_id) );
INSERT INTO app.company (delete_flag, company_name, company_address, company_email_id, max_users, created_by, created_date_time, updated_by, updated_date_time) VALUES (0, 'Default company', 'Patna', 'defaultcompany123@gmail.com', 6, -9, now(), -9, now());
CREATE TABLE IF NOT EXISTS app.user_role ( delete_flag INTEGER DEFAULT 0, role_id BIGSERIAL NOT NULL PRIMARY KEY, role_name VARCHAR(255) UNIQUE NOT NULL, created_by BIGINT, created_date_time TIMESTAMPTZ(6), updated_by BIGINT, updated_date_time TIMESTAMPTZ(6) );
INSERT INTO app.user_role (delete_flag, role_name, created_by, created_date_time, updated_by, updated_date_time) VALUES (0, 'Super Admin', -9, now(), -9, now()), (0, 'Admin', -9, now(), -9, now()), (0, 'Maintainer', -9, now(), -9, now()), (0, 'Guest', -9 , now(), -9, now());

rollback.sql:
DELETE FROM app.user_role 
WHERE role_name IN ('Super Admin', 'Admin', 'Maintainer', 'Guest');

DROP TABLE IF EXISTS app.user_role CASCADE;
DROP TABLE IF EXISTS app.company CASCADE;

changeSet.sql:
ALTER TABLE app.vendor ADD COLUMN company_id BIGINT;

UPDATE app.vendor 
SET company_id = (SELECT company_id FROM app.company WHERE company_name = 'Default company')
WHERE company_id IS NULL;

ALTER TABLE app.vendor 
ALTER COLUMN company_id SET NOT NULL,
ADD CONSTRAINT vendor_company_id_fkey 
FOREIGN KEY (company_id) REFERENCES app.company (company_id) ON DELETE CASCADE;

ALTER TABLE app.part ADD COLUMN company_id BIGINT;  

UPDATE app.part 
SET company_id = (SELECT company_id FROM app.company WHERE company_name = 'Default company')
WHERE company_id IS NULL;

ALTER TABLE app.part
