ADD CONSTRAINT part_company_id_fkey 
FOREIGN KEY (company_id) REFERENCES app.company (company_id) ON DELETE CASCADE;

ALTER TABLE app.part_category ADD COLUMN company_id BIGINT;  

UPDATE app.part_category 
