WHERE company_id IS NULL;

ALTER TABLE app.part_category
ALTER COLUMN company_id SET NOT NULL,
ADD CONSTRAINT part_category_company_id_fkey 
FOREIGN KEY (company_id) REFERENCES app.company (company_id) ON DELETE CASCADE;

rollback.sql:
ALTER TABLE app.part DROP CONSTRAINT part_company_id_fkey;
