ALTER TABLE app.cost_factor ADD COLUMN company_id BIGINT;

UPDATE app.cost_factor 
SET company_id = (SELECT company_id FROM app.company WHERE company_name = 'Default company')
WHERE company_id IS NULL;

ALTER TABLE app.cost_factor 
