ALTER TABLE app.app_user ADD COLUMN company_id BIGINT;
ALTER TABLE app.app_user ADD COLUMN role_id BIGINT;

UPDATE app.app_user 
SET company_id = (
    SELECT company_id FROM app.company WHERE company_name = 'Default company'
)
WHERE company_id IS NULL;

-- Set default role_id for existing users
UPDATE app.app_user 
SET role_id = (
    SELECT role_id FROM app.user_role WHERE role_name = 'Guest'
)
WHERE role_id IS NULL;

ALTER TABLE app.app_user
ALTER COLUMN company_id SET NOT NULL,
ALTER COLUMN role_id SET NOT NULL,
ADD CONSTRAINT app_user_company_id_fkey 
FOREIGN KEY (company_id) REFERENCES app.company (company_id) ON DELETE CASCADE,
ADD CONSTRAINT app_user_role_id_fkey 
FOREIGN KEY (role_id) REFERENCES app.user_role (role_id);

